// src/element-book/entries/vira-input.element.book.ts
var viraInputBookPage = defineBookPage({
	title: ViraInput.tagName,
	parent: elementsBookPage,
	descriptionParagraphs: ["Supports placeholders, suffixes, icons, disabling browser helps (like spellchecking), blocking/allowing specific inputs, etc.", "Has completely customizable sizing and coloring."],
	controls: {
		"Text color": {
			controlType: BookPageControlType.Color,
			initValue: viraFormCssVars["vira-form-foreground-color"].default
		},
		"Placeholder color": {
			controlType: BookPageControlType.Color,
			initValue: viraFormCssVars["vira-form-placeholder-color"].default
		},
		"Border color": {
			controlType: BookPageControlType.Color,
			initValue: viraFormCssVars["vira-form-border-color"].default
		},
		"Focus color": {
			controlType: BookPageControlType.Color,
			initValue: viraFormCssVars["vira-form-focus-outline-color"].default
		},
		"Selection color": {
			controlType: BookPageControlType.Color,
			initValue: viraFormCssVars["vira-form-text-selection-color"].default
		}
	},
	defineExamples({ defineExample }) {
		function defineInputExample({ styles, title, inputs }) {
			defineExample({
				title,
				styles: css`
                    ${styles || css``}
                `,
				state() {
					return { value: inputs.value };
				},
				render({ state, updateState, controls }) {
					const cssVarControlValues = {
						[String(viraFormCssVars["vira-form-foreground-color"].name)]: controls["Text color"],
						[String(viraFormCssVars["vira-form-placeholder-color"].name)]: controls["Placeholder color"],
						[String(viraFormCssVars["vira-form-border-color"].name)]: controls["Border color"],
						[String(viraFormCssVars["vira-form-focus-outline-color"].name)]: controls["Focus color"],
						[String(viraFormCssVars["vira-form-text-selection-color"].name)]: controls["Selection color"]
					};
					const cssVarValues = mapObjectValues(cssVarControlValues, (varName, controlValue) => {
						return controlValue || "inherit";
					});
					const styles = Object.entries(cssVarValues).map(([varName, varValue]) => {
						return [varName, varValue].join(": ") + ";";
					}).join("\n");
					return html`
                        <${ViraInput.assign({
						...inputs,
						value: state.value
					})}
                            style=${styles}
                            ${listen(ViraInput.events.valueChange, (event) => {
						updateState({ value: event.detail });
						console.info("changed:", event.detail);
					})}
                        ></${ViraInput}>
                    `;
				}
			});
		}
		[
			{
				title: "basic",
				inputs: { value: "default value" }
			},
			{
				title: "with icon",
				inputs: {
					value: "",
					icon: createSizedIcon(LucideCodeXmlIcon, 24)
				}
			},
			{
				title: "with placeholder",
				inputs: {
					value: "",
					placeholder: "placeholder here"
				}
			},
			{
				title: "with suffix",
				inputs: {
					value: "42",
					suffix: "px"
				}
			},
			{
				title: "with clear button",
				inputs: {
					value: "value",
					placeholder: "with clear",
					showClearButton: true
				}
			},
			{
				title: "disabled",
				inputs: {
					value: "disabled",
					disabled: true
				}
			},
			{
				title: "readonly",
				inputs: {
					label: "Label here",
					value: "readonly value",
					isReadonly: true
				}
			},
			{
				title: "numbers only",
				inputs: {
					value: "",
					allowedInputs: /\d/
				}
			},
			{
				title: "numbers blocked",
				inputs: {
					value: "",
					blockedInputs: /\d/
				}
			},
			{
				title: "custom width",
				styles: css`
                    ${ViraInput} {
                        width: 120px;
                    }
                `,
				inputs: {
					value: "",
					placeholder: "width",
					icon: createSizedIcon(LucideCodeXmlIcon, 24)
				}
			},
			{
				title: "taller height",
				styles: css`
                    ${ViraInput} {
                        height: 48px;
                    }
                `,
				inputs: {
					value: "",
					placeholder: "taller",
					icon: createSizedIcon(LucideCodeXmlIcon, 24)
				}
			},
			{
				title: "shorter height",
				styles: css`
                    ${ViraInput} {
                        height: 26px;
                    }
                `,
				inputs: {
					value: "",
					placeholder: "shorter",
					showClearButton: true,
					icon: createSizedIcon(LucideCodeXmlIcon, 24)
				}
			},
			{
				title: "max width",
				styles: css`
                    ${ViraInput} {
                        max-width: 150px;
                    }
                `,
				inputs: {
					value: "super long value that exceeds the max width",
					placeholder: "42"
				}
			},
			{
				title: "fit text",
				styles: css`
                    ${ViraInput} {
                        max-width: 150px;
                    }
                `,
				inputs: {
					value: "",
					placeholder: "42",
					fitText: true
				}
			},
			{
				title: "password",
				inputs: {
					value: "as password",
					type: ViraInputType.Password,
					attributePassthrough: { autocomplete: "new-password" }
				}
			},
			{
				title: "attribute passthrough",
				inputs: {
					value: "",
					attributePassthrough: { type: "number" }
				}
			},
			{
				title: "email username",
				inputs: {
					value: "",
					type: ViraInputType.Email,
					attributePassthrough: { autocomplete: "username" }
				}
			},
			{
				title: "centered",
				styles: css`
                    ${ViraInput} {
                        text-align: center;
                    }
                `,
				inputs: { value: "Abc" }
			},
			{
				title: "with error",
				inputs: {
					value: "has error",
					hasError: true
				}
			},
			{
				title: "with label",
				inputs: {
					label: "Label here",
					placeholder: "has label",
					value: ""
				}
			},
			{
				title: "with long label",
				inputs: {
					label: "Enter a really really really really long value",
					placeholder: "has label",
					value: ""
				}
			},
			{
				title: "with unbound long label",
				inputs: {
					label: "Enter a really really really really long value",
					placeholder: "has label",
					value: ""
				},
				styles: css`
                    ${ViraInput} {
                        width: unset;
                    }
                `
			}
		].forEach(defineInputExample);
	}
});
